+// isEntireIDEHook checks if an IDE hook file belongs to Entire.
+func isEntireIDEHook(hook kiroIDEHookFile) bool {
+	return strings.HasPrefix(hook.Name, "entire-") && isEntireHook(hook.Then.Command)
+}

